CREATE OR REPLACE FUNCTION public.touch_course_updated_at()
RETURNS trigger
LANGUAGE plpgsql
SET search_path = ''
AS $$
BEGIN
  NEW.updated_at = now();
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS touch_levels_updated_at ON public.levels;
CREATE TRIGGER touch_levels_updated_at BEFORE UPDATE ON public.levels FOR EACH ROW EXECUTE FUNCTION public.touch_course_updated_at();
DROP TRIGGER IF EXISTS touch_series_updated_at ON public.series;
