CREATE OR REPLACE FUNCTION public.can_access_course_target(target_level_id uuid, target_series_id uuid)
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = ''
AS $$
  SELECT (select public.is_edutech_admin()) OR EXISTS (
    SELECT 1
    FROM public.profiles AS p
    JOIN public.levels AS l ON l.id = target_level_id
    LEFT JOIN public.series AS s ON s.id = target_series_id
    WHERE p.id = (select auth.uid())
      AND p.is_active IS TRUE
      AND p.school_level = l.name
      AND (target_series_id IS NULL OR p.series = s.name)
  );
$$;

GRANT EXECUTE ON FUNCTION public.is_edutech_admin() TO authenticated;
GRANT EXECUTE ON FUNCTION public.can_access_course_target(uuid, uuid) TO authenticated;

